import { useEffect, useMemo, useState } from "react";
import { MenuSurface } from "./surface";
import { ChoiceEntry } from "./entry";
import { ContentBox, ContentList } from "./content";
import { NativeTrigger } from "./trigger";
import { groupRows } from "./group";
import { ActionButton } from "./action";
export const Picker = ({ values, options, onPendingChange, isSearchable, onSearch, isLoading, disabled, triggerComponent, isClearable }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [draft, setDraft] = useState(values);
  useEffect(() => { setDraft(values); onPendingChange?.(values); }, [JSON.stringify(values)]);
  const toggleChoice = (event, selectedValue) => {
    event.preventDefault();
    if (selectedValue === undefined) return;
    if (draft.includes(selectedValue)) {
      const next = draft.filter((entry) => entry !== selectedValue);
      setDraft(next);
      onPendingChange?.(next);
    } else {
      const next = [...draft, selectedValue];
      setDraft(next);
      onPendingChange?.(next);
    }
  };
  const commitChoice = (nextValues) => { onPendingChange?.(nextValues); setIsOpen(false); };
  const clearChoice = () => { onPendingChange?.([]); };
  const renderChoice = (option) => {
    const { value: choiceValue, category, ...optionRest } = option;
    const choiceProps = { value: choiceValue, onSelect: (event) => toggleChoice(event, choiceValue), startIcon: draft.includes(choiceValue) ? "Selected" : "Unselected", ...optionRest };
    return <ChoiceEntry {...choiceProps} />;
  };
  const displayOptions = isSearchable && !onSearch ? options.filter((option) => option.label) : options;
  const groups = useMemo(() => groupRows(displayOptions), [displayOptions]);
  return <MenuSurface open={isOpen} onOpenChange={setIsOpen} disabled={disabled} triggerComponent={triggerComponent ?? <NativeTrigger disabled={disabled} valueLabel={draft.length ? "Chosen" : ""} onClear={clearChoice} isClearable={isClearable} isLoading={isLoading} />}>
    <ContentBox><ContentList disabled={isLoading}>
      {groups ? Object.entries(groups).map(([category, categoryOptions]) => <div>{categoryOptions.map(renderChoice)}</div>) : displayOptions.map(renderChoice)}
    </ContentList></ContentBox>
    <ActionButton onClick={() => commitChoice(draft)}>Apply</ActionButton>
  </MenuSurface>;
};

