import * as Menu from "@radix-ui/react-dropdown-menu";
export const MenuSurface = ({ children, triggerComponent, open, onOpenChange, disabled }) => {
  return <Menu.Root open={open} onOpenChange={onOpenChange} modal={false}>
    <Menu.Trigger asChild disabled={disabled}>{triggerComponent}</Menu.Trigger>
    <Menu.Content style={{ zIndex: 5 }}>{children}</Menu.Content>
  </Menu.Root>;
};

