import { useEffect } from "react";
export const ContentBox = ({ children, ...props }) => {
  useEffect(() => {}, [children]);
  return <div {...props}>{children}</div>;
};
export const ContentList = ({ children, disabled }) => {
  return <div className={disabled ? "disabled" : "enabled"}>{children}</div>;
};

