import { forwardRef } from "react";
export const NativeTrigger = forwardRef(({ valueLabel, onClear, isClearable, isLoading, variant = "default", ...props }, ref) => {
  const displayValue = valueLabel || "Choose";
  const showClearButton = valueLabel && isClearable;
  const clearSelection = (event) => { event.stopPropagation(); event.preventDefault(); onClear?.(); };
  if (variant === "ghost") { return <Alternate ref={ref} {...props}>{displayValue}</Alternate>; }
  return <button ref={ref} {...props}><span>{displayValue}</span>{showClearButton && <span onPointerDown={clearSelection}>Clear</span>}{isLoading ? "Loading" : "Open"}</button>;
});

